import unittest
from solution import parse_tag_table


class ParseTagTableTests(unittest.TestCase):
    def test_normal_document_preserves_line_and_tag_order(self):
        text = "2 alpha beta_2\n10 z9 first_tag\n1 final"
        self.assertEqual(parse_tag_table(text), [
            {"id": 2, "tags": ["alpha", "beta_2"]},
            {"id": 10, "tags": ["z9", "first_tag"]},
            {"id": 1, "tags": ["final"]},
        ])

    def test_blank_lines_and_general_whitespace_are_ignored_or_separate_fields(self):
        text = "  \n\t3\talpha   beta\r\n\n4 gamma\t"
        self.assertEqual(parse_tag_table(text), [
            {"id": 3, "tags": ["alpha", "beta"]},
            {"id": 4, "tags": ["gamma"]},
        ])

    def test_empty_and_blank_documents(self):
        self.assertEqual(parse_tag_table(""), [])
        self.assertEqual(parse_tag_table(" \n\t\r\n"), [])

    def test_results_are_freshly_allocated(self):
        first = parse_tag_table("1 a b")
        second = parse_tag_table("1 a b")
        self.assertIsNot(first, second)
        self.assertIsNot(first[0], second[0])
        self.assertIsNot(first[0]["tags"], second[0]["tags"])
        first[0]["tags"].append("changed")
        self.assertEqual(second, [{"id": 1, "tags": ["a", "b"]}])

    def test_non_string_is_type_error(self):
        for value in (None, b"1 a", ["1 a"]):
            with self.subTest(value=value), self.assertRaises(TypeError):
                parse_tag_table(value)

    def test_malformed_identifiers_and_missing_tags(self):
        malformed = [
            "1", "0 tag", "-1 tag", "+1 tag", "1.0 tag",
            "１２ tag", "1a tag", "a tag",
        ]
        for text in malformed:
            with self.subTest(text=text), self.assertRaises(ValueError):
                parse_tag_table(text)

    def test_invalid_tags(self):
        malformed = [
            "1 Upper", "1 hyphen-tag", "1 café", "1 a.b", "1 _ok !",
        ]
        for text in malformed:
            with self.subTest(text=text), self.assertRaises(ValueError):
                parse_tag_table(text)

    def test_duplicate_identifier_or_tag(self):
        with self.assertRaises(ValueError):
            parse_tag_table("1 a\n2 b\n1 c")
        with self.assertRaises(ValueError):
            parse_tag_table("1 a b a")
        self.assertEqual(parse_tag_table("1 a\n2 a"), [
            {"id": 1, "tags": ["a"]}, {"id": 2, "tags": ["a"]}
        ])


if __name__ == "__main__":
    unittest.main()

